<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\CartRecoveryService;
class CartRecoveryController extends Controller {public function saveEmail(Request $request,CartRecoveryService $service){$this->validate($request,['email'=>'required|email|max:150']);$request->session()->put('cart_email',strtolower(trim($request->email)));$service->capture($request);return redirect()->back()->with('success','Recovery email saved for this cart.');}public function restore(Request $request,$token){$saved=DB::table('abandoned_carts')->where('recovery_token',$token)->whereIn('status',['active','reminded'])->first();abort_unless($saved,404);$items=(array)json_decode($saved->items,true);$valid=DB::table('product')->whereIn('id',array_keys($items))->where('publication_status',1)->pluck('id')->map(function($id){return (string)$id;})->all();$cart=[];foreach($items as $id=>$qty)if(in_array((string)$id,$valid,true))$cart[$id]=max(1,(int)$qty);$request->session()->put('cart',$cart);$request->session()->put('abandoned_cart_id',$saved->id);DB::table('abandoned_carts')->where('id',$saved->id)->update(['status'=>'recovered','recovered_at'=>now(),'updated_at'=>now()]);return redirect()->route('cart.index')->with('success','Your saved cart has been restored.');}}
